SELECT
    (COUNT(CASE WHEN fd.language = 'Chinese Simplified' THEN fd.id END) * 100.0) / COUNT(fd.id) AS percentage
FROM foreign_data AS fd;

SELECT
    (
        SUM(CASE WHEN z.state = 'New Jersey' THEN 1 ELSE 0 END) * 1.0 / COUNT(CASE WHEN m.position = 'Member' THEN 1 END)
    ) - (
        SUM(CASE WHEN z.state = 'Vermont' THEN 1 ELSE 0 END) * 1.0 / COUNT(CASE WHEN m.position = 'Member' THEN 1 END)
    ) AS percentage_difference
FROM member m
JOIN zip_code z
    ON m.zip = z.zip_code;
